/**
 * Ownership offers. Every query is filtered by `orgId`.
 *
 * A lapsed offer stays `pending` in its row until `expireLapsedHandovers()`
 * closes it, so readers must compare `expiresAt` with the clock as well as
 * reading the status. The service layer owns that decision.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq, gt, lte, or, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

export interface InsertOwnershipHandoverInput {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}

/** The stored `pending` row, lapsed or not. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function insertHandover(
  input: InsertOwnershipHandoverInput,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();
  return toOwnershipHandover(row);
}

/** Moves one open offer to a terminal state; the `pending` guard keeps it single-use. */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${handoverId} is not pending`);
  return toOwnershipHandover(row);
}

/**
 * Closes every pending offer whose window has passed. Each one is resolved at
 * the instant it lapsed, not at the instant of this sweep.
 */
export async function expireLapsedHandovers(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({
      status: "expired",
      resolvedAt: sql`${ownershipHandovers.expiresAt}`,
      updatedAt: now,
    })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        lte(ownershipHandovers.expiresAt, now),
      ),
    )
    .run();
}

/**
 * Withdraws every open offer that names `userId` as offerer or offeree. Called
 * when that member leaves the workspace, since an offer cannot outlive either side.
 */
export async function cancelOpenHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<readonly OwnershipHandover[]> {
  const rows = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: now, updatedAt: now })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, now),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .returning()
    .all();
  return rows.map(toOwnershipHandover);
}

