export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Only the recorded owner may offer or withdraw. The owner role is checked
 * too, but holding it is not enough: a second owner-role member is refused here.
 */
async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:transfer_ownership", orgResource(orgId));

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:transfer_ownership", {
      action: "org:transfer_ownership",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

/** An offer is live strictly before `expiresAt`; from that instant on it has lapsed. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return Date.parse(handover.expiresAt) <= now.getTime();
}

/** The open offer, or `null` when none is open or the stored one has lapsed. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (pending === null || hasLapsed(pending, now)) return null;
  return pending;
}

/**
 * The offer the actor is allowed to accept or decline. Only the offeree may act
 * on it; a lapsed offer is `expired` for the offeree and invisible to anyone else.
 */
async function findActionableHandover(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/**
 * Offers the workspace to another active member. Only one offer may be open at
 * a time, and the offeree is the only person alerted.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (target?.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  // Lapsed offers are closed first, so they cannot block the open-offer check.
  await ownershipHandoverRepo.expireLapsedHandovers(orgId, toIsoTimestamp(now));
  if ((await findOpenHandover(orgId, now)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await ownershipHandoverRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(
      new Date(now.getTime() + OWNERSHIP_HANDOVER_WINDOW_MS),
    ),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: "Accept within seven days to become its owner, or decline.",
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offeree takes over. The incoming member is promoted before the previous
 * owner steps down, so the workspace always has at least one owner. Every role
 * change is announced as a manual one would be, on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const at = new Date();
  const handover = await findActionableHandover(actor, orgId, at);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, handover.toUserId),
    "Member",
    handover.toUserId,
  );
  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(
      orgId,
      incoming.id,
      "owner",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  await orgRepo.setOrgOwner(orgId, handover.toUserId);

  // Read after the promotion: the previous owner's role may have changed since the offer was made.
  const outgoing = requireFound(
    await memberRepo.findMember(orgId, handover.fromUserId),
    "Member",
    handover.fromUserId,
  );
  if (outgoing.role === "owner") {
    const steppedDown = await memberRepo.updateMemberRole(
      orgId,
      outgoing.id,
      "admin",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: steppedDown.id,
      from: outgoing.role,
      to: steppedDown.role,
    });
  }

  await ownershipHandoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(at),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** The offeree turns the offer down. Nothing changes, and the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const at = new Date();
  const handover = await findActionableHandover(actor, orgId, at);

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(at),
  );
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);

  const at = new Date();
  const open = await findOpenHandover(orgId, at);
  if (open === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    toIsoTimestamp(at),
  );
}

/** The open offer, if any. Visible to every member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return findOpenHandover(orgId, new Date());
}

