/**
 * Ownership handover: offer, accept, decline, withdraw, the seven-day window,
 * and the consequences that follow the recorded owner.
 *
 * Each case builds its own tenant so offers never leak between cases.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit, subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import type { OwnershipHandoverRefusal } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as billingService from "@/server/services/billing-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";
import type { Actor } from "@/types/member";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const WINDOW_MS = 7 * DAY_MS;
const UNKNOWN_USER = "01HZZZZZZZZZZZZZZZZZZZZZZZ" as UserId;

let cleanup: () => void;
let detachActivity: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** The actor a request would hold after any role change, resolved from stored state. */
async function actorFor(tenant: Tenant, userId: UserId): Promise<Actor> {
  const actor = await memberService.resolveActor(userId, tenant.org.id);
  if (actor === null) throw new Error("fixture member is not active");
  return actor;
}

/** Collects every payload delivered for one event type until `stop()` is called. */
function collect<K extends TaskflowEventType>(type: K): {
  readonly seen: TaskflowEventMap[K][];
  readonly stop: Unsubscribe;
} {
  const seen: TaskflowEventMap[K][] = [];
  const stop = subscribe(type, (payload) => {
    seen.push(payload);
  });
  return { seen, stop };
}

async function expectRefusal(
  promise: Promise<unknown>,
  reason: OwnershipHandoverRefusal,
): Promise<void> {
  await expect(promise).rejects.toBeInstanceOf(OwnershipHandoverError);
  await expect(promise).rejects.toMatchObject({ reason, code: "conflict" });
}

async function notificationKinds(
  actor: Actor,
  orgId: OrgId,
  recipientId: UserId,
): Promise<readonly string[]> {
  const page = await listNotifications(actor, {
    orgId,
    recipientId,
    unreadOnly: false,
    limit: 25,
    cursor: null,
  });
  return page.items.map((item) => item.kind);
}

describe("ownership handover: offering", () => {
  it("records a pending offer that lapses exactly seven days after it was made", async () => {
    const tenant = await createTenant("handover-offer");

    const handover = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    expect(handover).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.admin,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(handover.expiresAt) - Date.parse(handover.createdAt)).toBe(WINDOW_MS);

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toMatchObject({ id: handover.id });
  });

  it("alerts only the offered member with the ownership_handover kind", async () => {
    const tenant = await createTenant("handover-alert");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const offeree = await actorFor(tenant, tenant.userIds.admin);
    const owner = await actorFor(tenant, tenant.userIds.owner);
    const member = await actorFor(tenant, tenant.userIds.member);

    await expect(
      notificationKinds(offeree, tenant.org.id, tenant.userIds.admin),
    ).resolves.toEqual(["ownership_handover"]);
    await expect(
      notificationKinds(owner, tenant.org.id, tenant.userIds.owner),
    ).resolves.toEqual([]);
    await expect(
      notificationKinds(member, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual([]);
  });

  it("refuses to offer the workspace to its owner", async () => {
    const tenant = await createTenant("handover-self");

    await expectRefusal(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.owner,
      ),
      "self",
    );
  });

  it("allows only one open offer at a time", async () => {
    const tenant = await createTenant("handover-single");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    await expectRefusal(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
      "pending_exists",
    );
  });

  it("refuses an offer to a user who is not an active member of this workspace", async () => {
    const tenant = await createTenant("handover-targets");
    const outsider = await createTenant("handover-outsider");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        UNKNOWN_USER,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        outsider.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an offer from an owner-role member who is not the recorded owner", async () => {
    const tenant = await createTenant("handover-second-owner");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))!.id,
      role: "owner",
    });
    const secondOwner = await actorFor(tenant, tenant.userIds.admin);

    await expect(
      organizationService.initiateOwnershipHandover(
        secondOwner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses every operation across a workspace boundary", async () => {
    const home = await createTenant("handover-home");
    const away = await createTenant("handover-away");

    await expect(
      organizationService.initiateOwnershipHandover(
        home.actors.owner,
        away.org.id,
        home.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.acceptOwnershipHandover(home.actors.admin, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.declineOwnershipHandover(home.actors.admin, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.cancelOwnershipHandover(home.actors.owner, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.getPendingOwnershipHandover(home.actors.viewer, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    // An offer made in one workspace is invisible from the other.
    await organizationService.initiateOwnershipHandover(
      home.actors.owner,
      home.org.id,
      home.userIds.admin,
    );
    await expect(
      organizationService.getPendingOwnershipHandover(away.actors.owner, away.org.id),
    ).resolves.toBeNull();
  });
});

describe("ownership handover: accepting", () => {
  it("hands the workspace to the accepting member and steps the previous owner down to admin", async () => {
    const tenant = await createTenant("handover-accept");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const roles = collect("member.role_changed");
    const transfers = collect("organization.ownership_transferred");
    const org = await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );
    roles.stop();
    transfers.stop();

    expect(org.ownerId).toBe(tenant.userIds.admin);
    expect((await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))?.role).toBe("owner");
    expect((await memberRepo.findMember(tenant.org.id, tenant.userIds.owner))?.role).toBe("admin");

    expect(roles.seen.map(({ from, to, actorId }) => ({ from, to, actorId }))).toEqual([
      { from: "admin", to: "owner", actorId: tenant.userIds.admin },
      { from: "owner", to: "admin", actorId: tenant.userIds.admin },
    ]);
    expect(transfers.seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.admin,
      }),
    ]);
  });

  it("writes one audit row for the transfer, on the organization", async () => {
    const tenant = await createTenant("handover-audit");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );

    const page = await listActivity(await actorFor(tenant, tenant.userIds.admin), {
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.admin },
    });
  });

  it("accepts from any role, including viewer", async () => {
    const tenant = await createTenant("handover-viewer");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    const org = await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.viewer),
      tenant.org.id,
    );

    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect((await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer))?.role).toBe("owner");
  });

  it("changes only the previous owner's role when the offeree already holds the owner role", async () => {
    const tenant = await createTenant("handover-already-owner");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))!.id,
      role: "owner",
    });
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const roles = collect("member.role_changed");
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );
    roles.stop();

    expect(roles.seen.map(({ from, to }) => ({ from, to }))).toEqual([
      { from: "owner", to: "admin" },
    ]);
  });

  it("refuses acceptance by anyone but the offeree, and refuses a second acceptance", async () => {
    const tenant = await createTenant("handover-accept-guard");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    await expectRefusal(
      organizationService.acceptOwnershipHandover(
        await actorFor(tenant, tenant.userIds.member),
        tenant.org.id,
      ),
      "nothing_pending",
    );
    await expectRefusal(
      organizationService.acceptOwnershipHandover(tenant.actors.owner, tenant.org.id),
      "nothing_pending",
    );

    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );
    await expectRefusal(
      organizationService.acceptOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
      "nothing_pending",
    );
  });

  it("moves alerts about new members and billing to the new owner", async () => {
    const tenant = await createTenant("handover-consequences");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );

    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewerMember) throw new Error("fixture member missing");
    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      memberId: viewerMember.id,
      userId: tenant.userIds.viewer,
      role: "viewer",
    });

    const previous = await actorFor(tenant, tenant.userIds.owner);
    await expect(
      notificationKinds(await actorFor(tenant, tenant.userIds.admin), tenant.org.id, tenant.userIds.admin),
    ).resolves.toContain("member_joined");
    await expect(
      notificationKinds(previous, tenant.org.id, tenant.userIds.owner),
    ).resolves.not.toContain("member_joined");

    await expect(
      billingService.changePlan(previous, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const plan = await billingService.changePlan(await actorFor(tenant, tenant.userIds.admin), {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });
    expect(plan.plan).toBe("enterprise");
  });

  it("lets the new owner remove the previous owner, now an admin", async () => {
    const tenant = await createTenant("handover-remove-previous");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );

    const previousOwner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!previousOwner) throw new Error("fixture member missing");
    const removed = await memberService.removeMember(
      await actorFor(tenant, tenant.userIds.admin),
      { orgId: tenant.org.id, memberId: previousOwner.id },
    );

    expect(removed.userId).toBe(tenant.userIds.owner);
  });
});

describe("ownership handover: declining and withdrawing", () => {
  it("lets the offeree decline, leaving nothing pending and the owner free to offer again", async () => {
    const tenant = await createTenant("handover-decline");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const declined = await organizationService.declineOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );
    expect(declined).toMatchObject({ status: "declined", toUserId: tenant.userIds.admin });
    expect(declined.resolvedAt).not.toBeNull();

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();
    await expectRefusal(
      organizationService.declineOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
      "nothing_pending",
    );
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("lets the recorded owner withdraw an open offer, and refuses a second withdrawal", async () => {
    const tenant = await createTenant("handover-withdraw");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const canceled = await organizationService.cancelOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(canceled).toMatchObject({ status: "canceled" });
    expect(canceled.resolvedAt).not.toBeNull();

    await expectRefusal(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
      "nothing_pending",
    );
    await expectRefusal(
      organizationService.declineOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
      "nothing_pending",
    );
  });

  it("refuses withdrawal by a member who is not the recorded owner", async () => {
    const tenant = await createTenant("handover-withdraw-guard");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    await expect(
      organizationService.cancelOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toMatchObject({ toUserId: tenant.userIds.admin });
  });

  it("refuses withdrawal when nothing is open", async () => {
    const tenant = await createTenant("handover-withdraw-empty");

    await expectRefusal(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
      "nothing_pending",
    );
  });

  it("withdraws the offer when the offeree leaves the workspace", async () => {
    const tenant = await createTenant("handover-offeree-removed");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const offeree = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!offeree) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: offeree.id,
    });

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("withdraws the offer when the offering owner leaves and another owner remains", async () => {
    const tenant = await createTenant("handover-offerer-removed");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))!.id,
      role: "owner",
    });
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    const offerer = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!offerer) throw new Error("fixture member missing");
    await memberService.removeMember(await actorFor(tenant, tenant.userIds.admin), {
      orgId: tenant.org.id,
      memberId: offerer.id,
    });

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();
  });
});

describe("ownership handover: the seven-day window", () => {
  it("is open strictly before seven days have passed and lapsed from that instant on", async () => {
    const tenant = await createTenant("handover-expiry");
    const start = new Date("2026-10-08T09:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    const handover = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(handover.expiresAt).toBe(new Date(start.getTime() + WINDOW_MS).toISOString());

    vi.setSystemTime(new Date(start.getTime() + WINDOW_MS - 1));
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toMatchObject({ id: handover.id });

    vi.setSystemTime(new Date(start.getTime() + WINDOW_MS));
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();
    await expectRefusal(
      organizationService.acceptOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
      "expired",
    );
    await expectRefusal(
      organizationService.declineOwnershipHandover(
        await actorFor(tenant, tenant.userIds.admin),
        tenant.org.id,
      ),
      "expired",
    );
    await expectRefusal(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
      "nothing_pending",
    );

    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.ownerId).toBe(tenant.userIds.owner);
  });

  it("lets a lapsed offer be replaced by a fresh one", async () => {
    const tenant = await createTenant("handover-replace");
    const start = new Date("2026-10-08T09:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    const first = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    vi.setSystemTime(new Date(start.getTime() + WINDOW_MS));
    const second = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(second.id).not.toBe(first.id);
    expect(second).toMatchObject({ status: "pending", toUserId: tenant.userIds.member });
    expect(second.expiresAt).toBe(new Date(start.getTime() + 2 * WINDOW_MS).toISOString());
  });
});

